pub fn package_tree_entry_canonical_line(entry: Rc<PackageTreeEntryReceipt>) -> String {
    match (*entry.kind.clone()).clone() {
    PackageTreeEntryKind::PackageTreeRegularFile { content_digest: content_digest, .. } => v1_rt::concat("f\t".to_string(), v1_rt::concat(entry.mode_octal.clone(), v1_rt::concat("\t".to_string(), v1_rt::concat(entry.rel_path.clone(), v1_rt::concat("\t".to_string(), content_digest.hex.clone()))))),
    PackageTreeEntryKind::PackageTreeSymlink { target: target, .. } => v1_rt::concat("l\t".to_string(), v1_rt::concat(entry.mode_octal.clone(), v1_rt::concat("\t".to_string(), v1_rt::concat(entry.rel_path.clone(), v1_rt::concat("\t".to_string(), target.clone()))))),
}
}

pub fn package_materialized_tree_observation_note() -> String {
    thread_local! {
        static CACHED: String = {
            "TYPED FIND, TYPED REFUSAL (review 50535). This read previously built its argv by concat-ing the root into a single-quoted find string and running it through retained_foreign — medium-as-string (gunbc.design_argument::self_hosting), and a root containing an apostrophe escaped the wrapper outright. extdeps.shell already owned shell.Find, so the string form was also a gunbc.design_argument::single_authority fork of an existing authority: the enumeration now goes through shell.Find.FilesAndSymlinksWithMode, where root is a distinct argv element and no quoting exists to escape. The trailing pipe to sort is gone too — std sort orders the rows in-substrate rather than borrowing the shell's collation, which is locale-dependent and was never declared.\n\nThe refusal half: every failure arm returned a bare none, so a missing find, a permission denial, an uninterpretable row, a digest failure and a write failure were one indistinguishable Absent and the caller's cause string was canned regardless of what actually happened (gunbc.design_argument::fail_closed — a failure arm must refuse, and the refusal must be typed and located to be countable). Each arm now names its own cause. NOT a state this fixes, stated because the review named it: an EMPTY tree was never ambiguous — it returns an Observed receipt carrying zero entries, not a refusal.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum PackageMaterializedTreeObservation {
    PackageMaterializedTreeObserved {
        receipt: Rc<PackageMaterializedTreeReceipt>,
    },
    PackageMaterializedTreeObservationRefused {
        cause: NonEmptyStr,
    },
}

pub async fn observe_package_materialized_tree(root: String, work_dir: String, shell_find: &Shell__Find, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512) -> std::result::Result<Rc<PackageMaterializedTreeObservation>, std::boxed::Box<dyn std::error::Error>> {
    let listed = shell_find.files_and_symlinks_with_mode(root.clone()).await?;
Ok(if (listed.0.clone() == false) {
        Rc::new(PackageMaterializedTreeObservation::PackageMaterializedTreeObservationRefused {
    cause: "installed-tree enumeration command failed".to_string(),
})
    } else {
        {
            let rows = Rc::new(listed.1.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<String>>, line: String| if (line.clone() == "".to_string()) {
                acc
            } else {
                v1_rt::rc_list_push(acc, line.clone())
            });
let entries_acc = { let mut __fold_acc: Option<Rc<Vec<Rc<PackageTreeEntryReceipt>>>> = Some(Rc::new(vec![])); for __fold_elem in rows.iter().cloned() { let acc = __fold_acc; let row = __fold_elem; __fold_acc = { match acc.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(so_far) => {
                let cols = Rc::new(row.clone().split(&"\t".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
match cols.clone().get((0) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(kind_ch) => match cols.clone().get((1) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(mode) => match cols.clone().get((2) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(rel) => if ((rel.clone() == "".to_string()) || (rel.clone() == codex_runtime_receipt_sidecar_name())) {
                    Some(so_far.clone())
                } else {
                    if (kind_ch.clone() == "f".to_string()) {
                        {
                            let abs = v1_rt::concat(root.clone(), v1_rt::concat("/".to_string(), rel.clone()));
match observe_file_sha512(abs.clone(), sha512sum_sha512).await? {
    std::option::Option::None => std::option::Option::None,
    Some(digest) => Some(v1_rt::rc_list_push(so_far.clone(), Rc::new(PackageTreeEntryReceipt {
    rel_path: rel.clone(),
    mode_octal: mode.clone(),
    kind: Rc::new(PackageTreeEntryKind::PackageTreeRegularFile {
    content_digest: digest.clone(),
}),
}))),
}
}
                    } else {
                        if (kind_ch.clone() == "l".to_string()) {
                            match cols.clone().get((3) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(target) => if (target.clone() == "".to_string()) {
                                std::option::Option::None
                            } else {
                                Some(v1_rt::rc_list_push(so_far.clone(), Rc::new(PackageTreeEntryReceipt {
    rel_path: rel.clone(),
    mode_octal: mode.clone(),
    kind: Rc::new(PackageTreeEntryKind::PackageTreeSymlink {
    target: target.clone(),
}),
})))
                            },
}
                        } else {
                            std::option::Option::None
                        }
                    }
                },
},
},
}
},
} }; } __fold_acc };
match entries_acc.clone() {
    std::option::Option::None => Rc::new(PackageMaterializedTreeObservation::PackageMaterializedTreeObservationRefused {
    cause: "installed-tree row could not be interpreted".to_string(),
}),
    Some(entries) => {
                let body = entries.iter().cloned().fold("".to_string(), |acc: String, entry: Rc<PackageTreeEntryReceipt>| v1_rt::concat(acc, v1_rt::concat(package_tree_entry_canonical_line(entry.clone()), "\n".to_string())));
let path = v1_rt::concat(work_dir.clone(), "/materialized-tree.canonical".to_string());
let wrote = filesystem.write(path.clone(), body.clone()).await?;
if (wrote.0.clone() == false) {
                    Rc::new(PackageMaterializedTreeObservation::PackageMaterializedTreeObservationRefused {
    cause: "canonical installed-tree listing could not be written".to_string(),
})
                } else {
                    match (*crate::extdeps_tools_sha512sum::sha512sum_observe_file(path.clone(), sha512sum_sha512).await?).clone() {
    Sha512FileObservation::Sha512FileObserved { digest: digest, .. } => Rc::new(PackageMaterializedTreeObservation::PackageMaterializedTreeObserved {
    receipt: Rc::new(PackageMaterializedTreeReceipt {
    entries: entries.clone(),
    tree_identity: crate::std_content_hash::as_content_hash_sha512(digest.clone()),
}),
}),
    Sha512FileObservation::Sha512FileObservationRefused { cause: digest_cause, .. } => Rc::new(PackageMaterializedTreeObservation::PackageMaterializedTreeObservationRefused {
    cause: digest_cause.clone(),
}),
}
                }
},
}
}
    })
}

pub fn json_object_keys_unique(members: Rc<Vec<Rc<JsonKeyValue>>>) -> bool {
    match members.iter().cloned().fold(Some(v1_rt::rc_empty_set::<String>()), |acc: Option<Rc<BTreeSet<String>>>, m: Rc<JsonKeyValue>| match acc.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(seen) => if v1_rt::set_contains(&seen, m.key.clone()) {
        std::option::Option::None
    } else {
        Some(v1_rt::rc_set_insert(seen.clone(), m.key.clone()))
    },
}) {
    std::option::Option::None => false,
    Some(_) => true,
}
}

pub fn sort_json_members_by_key(members: Rc<Vec<Rc<JsonKeyValue>>>) -> Rc<Vec<Rc<JsonKeyValue>>> {
    Rc::new({ let mut __keyed: Vec<_> = members.iter().cloned().map(|__e: Rc<JsonKeyValue>| { let __k = (|m: Rc<JsonKeyValue>| m.key.clone())(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() })
}

pub fn canonicalize_json_value(v: Rc<JsonValue>) -> Option<Rc<JsonValue>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*v.clone()).clone() {
    JsonValue::JsonNull => Some(Rc::new(JsonValue::JsonNull)),
    JsonValue::JsonBool { value: b, .. } => Some(Rc::new(JsonValue::JsonBool {
    value: b.clone(),
})),
    JsonValue::JsonNumber { lexeme: l, .. } => Some(Rc::new(JsonValue::JsonNumber {
    lexeme: l.clone(),
})),
    JsonValue::JsonString { value: s, .. } => Some(Rc::new(JsonValue::JsonString {
    value: s.clone(),
})),
    JsonValue::JsonArray { elements: elements, .. } => {
            let mapped = elements.iter().cloned().fold(Some(Rc::new(vec![])), |acc: Option<Rc<Vec<Rc<JsonValue>>>>, el: Rc<JsonValue>| match acc.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(so_far) => match canonicalize_json_value(el.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(c) => Some(v1_rt::rc_list_push(so_far.clone(), c.clone())),
},
});
match mapped.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(els) => Some(Rc::new(JsonValue::JsonArray {
    elements: els.clone(),
})),
}
},
    JsonValue::JsonObject { members: members, .. } => if (json_object_keys_unique(members.clone()) == false) {
            std::option::Option::None
        } else {
            {
                let sorted = sort_json_members_by_key(members.clone());
let mapped = sorted.iter().cloned().fold(Some(Rc::new(vec![])), |acc: Option<Rc<Vec<Rc<JsonKeyValue>>>>, m: Rc<JsonKeyValue>| match acc.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(so_far) => match canonicalize_json_value(m.value.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(cv) => Some(v1_rt::rc_list_push(so_far.clone(), Rc::new(JsonKeyValue {
    key: m.key.clone(),
    value: cv.clone(),
}))),
},
});
match mapped.clone() {
    std::option::Option::None => std::option::Option::None,
    Some(ms) => Some(Rc::new(JsonValue::JsonObject {
    members: ms.clone(),
})),
}
}
        },
}
    })
}

pub fn protocol_schema_relative_path(abs_s: String, schema_prefix: String) -> String {
    if v1_rt::starts_with(abs_s.clone(), schema_prefix.clone()) {
        v1_rt::substring(&abs_s, v1_rt::string_length(&schema_prefix), v1_rt::string_length(&abs_s))
    } else {
        abs_s.clone()
    }
}

pub fn protocol_schema_canonical_staging_path(work_dir: String, rel: String) -> String {
    v1_rt::concat(work_dir.clone(), v1_rt::concat("/schema-canonical/".to_string(), v1_rt::concat(crate::std_content_hash::content_hash_atom(rel.clone()).digest.clone(), ".canonical.json".to_string())))
}

pub async fn append_text_to_file(path: String, extra: String, filesystem: &Filesystem) -> std::result::Result<bool, std::boxed::Box<dyn std::error::Error>> {
    let existing = filesystem.read(path.clone()).await?;
Ok(if (existing.1.clone() == false) {
        false
    } else {
        filesystem.write(path.clone(), v1_rt::concat(existing.0.clone(), extra.clone())).await?.0.clone()
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ProtocolSchemaBundleFileStanding {
    BundleFileAdmitted,
    BundleFileUnreadable {
        path: String,
    },
    BundleFileNotDecodable {
        path: String,
    },
    BundleFileNotCanonicalizable {
        path: String,
    },
    BundleFileCanonicalWriteRefused {
        path: String,
    },
    BundleFileDigestRefused {
        path: String,
    },
    BundleFileManifestAppendRefused {
        path: String,
    },
}
impl ProtocolSchemaBundleFileStanding {
    pub fn path(&self) -> String {
        match self {
            ProtocolSchemaBundleFileStanding::BundleFileAdmitted => panic!("no path on unit variant"),
            ProtocolSchemaBundleFileStanding::BundleFileUnreadable { path: __val, .. } => __val.clone(),
            ProtocolSchemaBundleFileStanding::BundleFileNotDecodable { path: __val, .. } => __val.clone(),
            ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable { path: __val, .. } => __val.clone(),
            ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused { path: __val, .. } => __val.clone(),
            ProtocolSchemaBundleFileStanding::BundleFileDigestRefused { path: __val, .. } => __val.clone(),
            ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused { path: __val, .. } => __val.clone(),
        }
    }
}

pub fn protocol_schema_bundle_file_standing_text(standing: Rc<ProtocolSchemaBundleFileStanding>) -> String {
    match (*standing.clone()).clone() {
    ProtocolSchemaBundleFileStanding::BundleFileAdmitted => "admitted".to_string(),
    ProtocolSchemaBundleFileStanding::BundleFileUnreadable { path: path, .. } => v1_rt::concat("could not read ".to_string(), path.clone()),
    ProtocolSchemaBundleFileStanding::BundleFileNotDecodable { path: path, .. } => v1_rt::concat("not decodable as JSON: ".to_string(), path.clone()),
    ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable { path: path, .. } => v1_rt::concat("not canonicalizable: ".to_string(), path.clone()),
    ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused { path: path, .. } => v1_rt::concat("canonical staging write refused: ".to_string(), path.clone()),
    ProtocolSchemaBundleFileStanding::BundleFileDigestRefused { path: path, .. } => v1_rt::concat("digest refused: ".to_string(), path.clone()),
    ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused { path: path, .. } => v1_rt::concat("manifest append refused: ".to_string(), path.clone()),
}
}

pub async fn protocol_schema_process_file_for_bundle(abs_s: String, schema_prefix: String, work_dir: String, manifest_path: String, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512) -> std::result::Result<Rc<ProtocolSchemaBundleFileStanding>, std::boxed::Box<dyn std::error::Error>> {
    let rel = protocol_schema_relative_path(abs_s.clone(), schema_prefix);
let raw = filesystem.read(abs_s.clone()).await?;
Ok(if (raw.1.clone() == false) {
        Rc::new(ProtocolSchemaBundleFileStanding::BundleFileUnreadable {
    path: abs_s.clone(),
})
    } else {
        match (*crate::extdeps_languages_json_parse::parse_json_document(raw.0.clone())).clone() {
    JsonDocumentParse::JsonDocumentUnreadable { gap: _, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileNotDecodable {
    path: abs_s.clone(),
}),
    JsonDocumentParse::JsonDocumentParsed { value: parsed, .. } => match canonicalize_json_value(parsed.clone()) {
    std::option::Option::None => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable {
    path: abs_s.clone(),
}),
    Some(canon) => {
            let canon_body = crate::extdeps_languages_json_emit::serialize_json(canon.clone());
let canon_path = protocol_schema_canonical_staging_path(work_dir, rel.clone());
let wrote_canon = filesystem.write(canon_path.clone(), canon_body.clone()).await?.0.clone();
if (wrote_canon.clone() == false) {
                Rc::new(ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused {
    path: canon_path.clone(),
})
            } else {
                match (*crate::extdeps_tools_sha512sum::sha512sum_observe_file(canon_path.clone(), sha512sum_sha512).await?).clone() {
    Sha512FileObservation::Sha512FileObserved { digest: digest, .. } => if append_text_to_file(manifest_path.clone(), v1_rt::concat(rel.clone(), v1_rt::concat("\t".to_string(), v1_rt::concat(digest.hex.clone(), "\n".to_string()))), filesystem).await? {
                    Rc::new(ProtocolSchemaBundleFileStanding::BundleFileAdmitted)
                } else {
                    Rc::new(ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused {
    path: manifest_path.clone(),
})
                },
    Sha512FileObservation::Sha512FileObservationRefused { cause: _, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileDigestRefused {
    path: canon_path.clone(),
}),
}
            }
},
},
}
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ProtocolSchemaIdentityObservation {
    ProtocolSchemaIdentified {
        identity: Rc<ContentHash>,
    },
    ProtocolSchemaObservationRefused {
        cause: NonEmptyStr,
    },
}

pub async fn observe_protocol_schema_identity(native_executable: String, work_dir: String, shell_mkdir: &Shell__Mkdir, codex_app_server_cli: &Codex_app_server__Cli, shell_find: &Shell__Find, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512) -> std::result::Result<Rc<ProtocolSchemaIdentityObservation>, std::boxed::Box<dyn std::error::Error>> {
    let schema_dir = v1_rt::concat(work_dir.clone(), "/protocol-schema".to_string());
let made = shell_mkdir.parents(schema_dir.clone()).await?;
Ok(if (made.clone() == false) {
        Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "protocol schema staging directory could not be created".to_string(),
})
    } else {
        {
            let gen = codex_app_server_cli.generate_json_schema(Rc::new(CodexAppServerExecutable {
    path: native_executable.clone(),
}), schema_dir.clone()).await?;
if (gen.0.clone() == false) {
                Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the vendored executable refused to generate its protocol schema".to_string(),
})
            } else {
                {
                    let listed = shell_find.files_by_name_sorted(schema_dir.clone(), "*.json".to_string()).await?;
if (listed.0.clone() == false) {
                        Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the generated protocol schema directory could not be listed".to_string(),
})
                    } else {
                        {
                            let abs_paths = Rc::new({ let mut __result = Vec::new(); for p in Rc::new(listed.1.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned() { if (p.clone() != "".to_string()) { __result.push(p); } } __result });
if ((abs_paths.clone().len() as i64) == 0) {
                                Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the vendored executable generated no protocol schema files".to_string(),
})
                            } else {
                                {
                                    let schema_prefix = v1_rt::concat(schema_dir.clone(), "/".to_string());
let canon_staging_dir = v1_rt::concat(work_dir.clone(), "/schema-canonical".to_string());
let made_canon = shell_mkdir.parents(canon_staging_dir.clone()).await?;
let manifest_path = v1_rt::concat(work_dir.clone(), "/protocol-schema-bundle.manifest".to_string());
if (made_canon.clone() == false) {
                                        Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the canonical staging directory could not be created".to_string(),
})
                                    } else {
                                        {
                                            let init_manifest = filesystem.write(manifest_path.clone(), "".to_string()).await?;
if (init_manifest.0.clone() == false) {
                                                Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the bundle manifest could not be initialized".to_string(),
})
                                            } else {
                                                {
                                                    let bundle_standing = { let mut __fold_acc: Rc<ProtocolSchemaBundleFileStanding> = Rc::new(ProtocolSchemaBundleFileStanding::BundleFileAdmitted); for __fold_elem in abs_paths.iter().cloned() { let acc = __fold_acc; let abs = __fold_elem; __fold_acc = { match (*acc).clone() {
    ProtocolSchemaBundleFileStanding::BundleFileAdmitted => protocol_schema_process_file_for_bundle(abs.clone(), schema_prefix.clone(), work_dir.clone(), manifest_path.clone(), filesystem, sha512sum_sha512).await?,
    ProtocolSchemaBundleFileStanding::BundleFileUnreadable { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileUnreadable {
    path: p.clone(),
}),
    ProtocolSchemaBundleFileStanding::BundleFileNotDecodable { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileNotDecodable {
    path: p.clone(),
}),
    ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable {
    path: p.clone(),
}),
    ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused {
    path: p.clone(),
}),
    ProtocolSchemaBundleFileStanding::BundleFileDigestRefused { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileDigestRefused {
    path: p.clone(),
}),
    ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused { path: p, .. } => Rc::new(ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused {
    path: p.clone(),
}),
} }; } __fold_acc };
match (*bundle_standing.clone()).clone() {
    ProtocolSchemaBundleFileStanding::BundleFileAdmitted => match (*crate::extdeps_tools_sha512sum::sha512sum_observe_file(manifest_path.clone(), sha512sum_sha512).await?).clone() {
    Sha512FileObservation::Sha512FileObserved { digest: digest, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaIdentified {
    identity: crate::std_content_hash::as_content_hash_sha512(digest.clone()),
}),
    Sha512FileObservation::Sha512FileObservationRefused { cause: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: "the bundle manifest digest could not be observed".to_string(),
}),
},
    ProtocolSchemaBundleFileStanding::BundleFileUnreadable { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
    ProtocolSchemaBundleFileStanding::BundleFileNotDecodable { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
    ProtocolSchemaBundleFileStanding::BundleFileNotCanonicalizable { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
    ProtocolSchemaBundleFileStanding::BundleFileCanonicalWriteRefused { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
    ProtocolSchemaBundleFileStanding::BundleFileDigestRefused { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
    ProtocolSchemaBundleFileStanding::BundleFileManifestAppendRefused { path: _, .. } => Rc::new(ProtocolSchemaIdentityObservation::ProtocolSchemaObservationRefused {
    cause: v1_rt::concat("protocol schema bundle refused: ".to_string(), protocol_schema_bundle_file_standing_text(bundle_standing.clone())),
}),
}
}
                                            }
}
                                    }
}
                            }
}
                    }
}
            }
}
    })
}

pub fn codex_runtime_bundle_receipt_canonical_body(receipt: Rc<CodexRuntimeBundleReceipt>) -> Option<String> {
    match content_hash_sha512_hex(receipt.admitted_package_set_identity.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(set_hex) => match content_hash_sha512_hex(receipt.protocol_schema_identity.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(protocol_hex) => match content_hash_sha512_hex(receipt.materialized_tree.tree_identity.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(tree_hex) => Some(v1_rt::concat(receipt.manifest_digest.hex.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(receipt.lock_digest.hex.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(receipt.target.os.clone(), v1_rt::concat("/".to_string(), v1_rt::concat(receipt.target.cpu.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(set_hex.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(tree_hex.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(receipt.native_executable_digest.hex.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(receipt.toolchain.npm_cli_version.clone(), v1_rt::concat("\n".to_string(), v1_rt::concat(receipt.toolchain.node_version.clone(), v1_rt::concat("\n".to_string(), protocol_hex.clone()))))))))))))))))))),
},
},
}
}

pub async fn observe_codex_runtime_bundle_receipt_identity(receipt_without_identity: Rc<CodexRuntimeBundleReceipt>, staging_dir: String, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512) -> std::result::Result<Option<Rc<ContentHash>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match codex_runtime_bundle_receipt_canonical_body(receipt_without_identity) {
    std::option::Option::None => std::option::Option::None,
    Some(body) => {
        let path = v1_rt::concat(staging_dir.clone(), "/codex-runtime-bundle.receipt.canonical".to_string());
let wrote = filesystem.write(path.clone(), body.clone()).await?;
if (wrote.0.clone() == false) {
            std::option::Option::None
        } else {
            match (*crate::extdeps_tools_sha512sum::sha512sum_observe_file(path.clone(), sha512sum_sha512).await?).clone() {
    Sha512FileObservation::Sha512FileObserved { digest: digest, .. } => Some(crate::std_content_hash::as_content_hash_sha512(digest.clone())),
    Sha512FileObservation::Sha512FileObservationRefused { cause: _, .. } => std::option::Option::None,
}
        }
},
})
}

pub fn codex_runtime_receipt_sidecar_path(release_root: String) -> String {
    v1_rt::concat(release_root.clone(), v1_rt::concat("/".to_string(), codex_runtime_receipt_sidecar_name()))
}

pub async fn write_codex_runtime_receipt_sidecar(release_root: String, receipt_identity: Rc<ContentHash>, filesystem: &Filesystem) -> std::result::Result<bool, std::boxed::Box<dyn std::error::Error>> {
    Ok(match content_hash_sha512_hex(receipt_identity) {
    std::option::Option::None => false,
    Some(hex) => {
        let wrote = filesystem.write(codex_runtime_receipt_sidecar_path(release_root), hex.clone()).await?;
wrote.0.clone()
},
})
}

pub async fn read_codex_runtime_receipt_sidecar(release_root: String, filesystem: &Filesystem) -> std::result::Result<Option<String>, std::boxed::Box<dyn std::error::Error>> {
    let read = filesystem.read(codex_runtime_receipt_sidecar_path(release_root)).await?;
Ok(if (read.1.clone() == false) {
        std::option::Option::None
    } else {
        {
            let trimmed = v1_rt::trim(read.0.clone());
if (trimmed.clone() == "".to_string()) {
                std::option::Option::None
            } else {
                Some(trimmed.clone())
            }
}
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum CodexRuntimeReleaseOutcome {
    CodexRuntimeReleaseReady {
        root: FilePath,
    },
    CodexRuntimeReleaseFailed {
        cause: NonEmptyStr,
    },
    CodexRuntimeReleaseReuseMismatch {
        existing_root: FilePath,
        cause: NonEmptyStr,
    },
}

pub async fn validate_existing_codex_runtime_release(existing_root: String, receipt: Rc<CodexRuntimeBundleReceipt>, native_executable_rel: String, expected_hex: String, scratch_dir: String, shell_test: &Shell__Test, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512, shell_find: &Shell__Find) -> std::result::Result<Rc<CodexRuntimeReleaseOutcome>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match read_codex_runtime_receipt_sidecar(existing_root.clone(), filesystem).await? {
    std::option::Option::None => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release missing receipt sidecar".to_string(),
}),
    Some(side_hex) => if (side_hex.clone() != expected_hex.clone()) {
        Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release sidecar identity mismatch".to_string(),
})
    } else {
        {
            let existing_native = v1_rt::concat(existing_root.clone(), v1_rt::concat("/".to_string(), native_executable_rel.clone()));
match observe_file_sha512(existing_native.clone(), sha512sum_sha512).await? {
    std::option::Option::None => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release native digest observation refused".to_string(),
}),
    Some(observed) => if (observed.hex.clone() != receipt.native_executable_digest.hex.clone()) {
                Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release native digest mismatch".to_string(),
})
            } else {
                {
                    let native_file = shell_test.is_file(existing_native.clone()).await?;
let native_exec = shell_test.is_executable(existing_native.clone()).await?;
if ((native_file.clone() == false) || (native_exec.clone() == false)) {
                        Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release native entry is not a regular executable file".to_string(),
})
                    } else {
                        match (*observe_package_materialized_tree(existing_root.clone(), scratch_dir, shell_find, filesystem, sha512sum_sha512).await?).clone() {
    PackageMaterializedTreeObservation::PackageMaterializedTreeObservationRefused { cause: tree_cause, .. } => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: tree_cause.clone(),
}),
    PackageMaterializedTreeObservation::PackageMaterializedTreeObserved { receipt: tree, .. } => match content_hash_sha512_hex(tree.tree_identity.clone()) {
    std::option::Option::None => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release tree identity is not SHA-512".to_string(),
}),
    Some(tree_hex) => match content_hash_sha512_hex(receipt.materialized_tree.tree_identity.clone()) {
    std::option::Option::None => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "expected receipt tree identity is not SHA-512".to_string(),
}),
    Some(expected_tree_hex) => if (tree_hex.clone() != expected_tree_hex.clone()) {
                            Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: "existing release tree identity mismatch".to_string(),
})
                        } else {
                            Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReady {
    root: existing_root.clone(),
})
                        },
},
},
}
                    }
}
            },
}
}
    },
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum UniquePublishingRelocateOutcome {
    UniquePublishingRelocateReady {
        path: FilePath,
    },
    UniquePublishingPlaceholderNotEmpty,
    UniquePublishingRelocateRefused,
}
impl UniquePublishingRelocateOutcome {
    pub fn path(&self) -> FilePath {
        match self {
            UniquePublishingRelocateOutcome::UniquePublishingRelocateReady { path: __val, .. } => __val.clone(),
            UniquePublishingRelocateOutcome::UniquePublishingPlaceholderNotEmpty => panic!("no path on unit variant"),
            UniquePublishingRelocateOutcome::UniquePublishingRelocateRefused => panic!("no path on unit variant"),
        }
    }
}

pub async fn relocate_build_root_to_unique_publishing(build_root: String, parent: String, hex: String, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, shell_move: &Shell__Move) -> std::result::Result<Rc<UniquePublishingRelocateOutcome>, std::boxed::Box<dyn std::error::Error>> {
    let template = v1_rt::concat(parent.clone(), v1_rt::concat("/.".to_string(), v1_rt::concat(hex.clone(), ".publishing.XXXXXX".to_string())));
let staged = shell_mktemp.dir_with_template(template.clone()).await?;
Ok(if (staged.1.clone() == false) {
        Rc::new(UniquePublishingRelocateOutcome::UniquePublishingRelocateRefused)
    } else {
        {
            let emptied = shell_remove.empty_directory(staged.0.clone()).await?;
if (emptied.clone() == false) {
                Rc::new(UniquePublishingRelocateOutcome::UniquePublishingPlaceholderNotEmpty)
            } else {
                {
                    let moved = shell_move.no_replace_directory(build_root.clone(), staged.0.clone()).await?;
if (moved.clone() == false) {
                        {
                            let _ = shell_remove.recursive_force(staged.0.clone()).await?;
Rc::new(UniquePublishingRelocateOutcome::UniquePublishingRelocateRefused)
}
                    } else {
                        Rc::new(UniquePublishingRelocateOutcome::UniquePublishingRelocateReady {
    path: staged.0.clone(),
})
                    }
}
            }
}
    })
}

pub async fn rename_publishing_noreplace(publishing: String, dest: String, shell_move: &Shell__Move) -> std::result::Result<bool, std::boxed::Box<dyn std::error::Error>> {
    Ok(shell_move.no_replace_directory(publishing.clone(), dest.clone()).await?)
}

pub async fn codex_runtime_release_ready_with_current_link(release_parent: String, root: String, shell_exec: &Shell__Exec) -> std::result::Result<Rc<CodexRuntimeReleaseOutcome>, std::boxed::Box<dyn std::error::Error>> {
    Ok(if publish_codex_runtime_current_link(release_parent, root.clone(), shell_exec).await? {
        Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReady {
    root: root.clone(),
})
    } else {
        Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "codex runtime current symlink publish refused".to_string(),
})
    })
}

pub async fn release_codex_runtime_bundle_immutable(build_root: String, receipt: Rc<CodexRuntimeBundleReceipt>, native_executable_rel: String, scratch_dir: String, release_parent: String, shell_mkdir: &Shell__Mkdir, shell_test: &Shell__Test, shell_remove: &Shell__Remove, filesystem: &Filesystem, sha512sum_sha512: &Sha512sum__Sha512, shell_find: &Shell__Find, shell_exec: &Shell__Exec, shell_mktemp: &Shell__Mktemp, shell_move: &Shell__Move) -> std::result::Result<Rc<CodexRuntimeReleaseOutcome>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match content_hash_sha512_hex(receipt.receipt_identity.clone()) {
    std::option::Option::None => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "receipt identity is not SHA-512".to_string(),
}),
    Some(hex) => {
        let parent = release_parent.clone();
let made = shell_mkdir.parents(parent.clone()).await?;
if (made.clone() == false) {
            Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "release parent mkdir refused".to_string(),
})
        } else {
            {
                let dest = v1_rt::concat(parent.clone(), v1_rt::concat("/".to_string(), hex.clone()));
let already = shell_test.is_directory(dest.clone()).await?;
if already.clone() {
                    {
                        let validated = validate_existing_codex_runtime_release(dest.clone(), receipt.clone(), native_executable_rel.clone(), hex.clone(), scratch_dir.clone(), shell_test, filesystem, sha512sum_sha512, shell_find).await?;
match (*validated.clone()).clone() {
    CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReady { root: root, .. } => {
                            let _ = shell_remove.recursive_force(build_root.clone()).await?;
codex_runtime_release_ready_with_current_link(parent.clone(), root.clone(), shell_exec).await?
},
    CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed { cause: cause, .. } => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: cause.clone(),
}),
    CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch { existing_root, cause, .. } => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReuseMismatch {
    existing_root: existing_root.clone(),
    cause: cause.clone(),
}),
}
}
                } else {
                    match (*relocate_build_root_to_unique_publishing(build_root.clone(), parent.clone(), hex.clone(), shell_mktemp, shell_remove, shell_move).await?).clone() {
    UniquePublishingRelocateOutcome::UniquePublishingPlaceholderNotEmpty => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "unique publishing staging placeholder was not empty (exclusivity violation, not swept)".to_string(),
}),
    UniquePublishingRelocateOutcome::UniquePublishingRelocateRefused => Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "unique publishing staging relocate refused".to_string(),
}),
    UniquePublishingRelocateOutcome::UniquePublishingRelocateReady { path: publishing, .. } => if (write_codex_runtime_receipt_sidecar(publishing.clone(), receipt.receipt_identity.clone(), filesystem).await? == false) {
                        {
                            let _ = shell_remove.recursive_force(publishing.clone()).await?;
Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "receipt sidecar write refused on publishing staging".to_string(),
})
}
                    } else {
                        match (*validate_existing_codex_runtime_release(publishing.clone(), receipt.clone(), native_executable_rel.clone(), hex.clone(), scratch_dir.clone(), shell_test, filesystem, sha512sum_sha512, shell_find).await?).clone() {
    CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReady { root: _, .. } => if rename_publishing_noreplace(publishing.clone(), dest.clone(), shell_move).await? {
                            codex_runtime_release_ready_with_current_link(parent.clone(), dest.clone(), shell_exec).await?
                        } else {
                            {
                                let winner = shell_test.is_directory(dest.clone()).await?;
let _ = shell_remove.recursive_force(publishing.clone()).await?;
if winner.clone() {
                                    match (*validate_existing_codex_runtime_release(dest.clone(), receipt.clone(), native_executable_rel.clone(), hex.clone(), scratch_dir.clone(), shell_test, filesystem, sha512sum_sha512, shell_find).await?).clone() {
    CodexRuntimeReleaseOutcome::CodexRuntimeReleaseReady { root: winner_root, .. } => codex_runtime_release_ready_with_current_link(parent.clone(), winner_root.clone(), shell_exec).await?,
    other => { let other = Rc::new(other.clone()); other.clone() },
}
                                } else {
                                    Rc::new(CodexRuntimeReleaseOutcome::CodexRuntimeReleaseFailed {
    cause: "atomic no-replace rename to content-addressed release refused".to_string(),
})
                                }
}
                        },
    mismatch => { let mismatch = Rc::new(mismatch.clone()); {
                            let _ = shell_remove.recursive_force(publishing.clone()).await?;
mismatch.clone()
} },
}
                    },
}
                }
}
        }
},
})
}

