pub fn codex_runtime_materialization_failure_receipt(outcome: Rc<CodexRuntimeMaterialization>) -> String {
    {
        let generic = match codex_runtime_materialization_refusal_reason(outcome.clone()) {
    Some(reason) => reason.clone(),
    std::option::Option::None => "".to_string(),
};
match (*outcome.clone()).clone() {
    CodexRuntimeMaterialization::CodexRuntimeHostDependencyRefused { tool, hint, .. } => crate::gunbc_host_host_cli_dependency::host_dependency_absent_wire(tool.clone(), hint.clone()),
    CodexRuntimeMaterialization::CodexRuntimeMaterialized { bundle: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeLockRefused { admission: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeExactClosureRefused { closure: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeTargetObservationRefused { observation: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeAcquisitionRefused { acquisition: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeWorkspaceRefused { cause: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeCacheSeedRefused { .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeNpmCiOfflineRefused { stderr: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeExecutableAbsent { path: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimePlatformPackageAbsent { path: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeIdentityObservationRefused => generic,
    CodexRuntimeMaterialization::CodexRuntimeReceiptObservationRefused { cause: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeReleaseRefused { cause: _, .. } => generic,
    CodexRuntimeMaterialization::CodexRuntimeMaterializationReuseMismatch { .. } => generic,
}
}
}

pub fn codex_runtime_materialization_refusal_reason(outcome: Rc<CodexRuntimeMaterialization>) -> Option<String> {
    match (*outcome.clone()).clone() {
    CodexRuntimeMaterialization::CodexRuntimeMaterialized { bundle: _, .. } => std::option::Option::None,
    CodexRuntimeMaterialization::CodexRuntimeLockRefused { admission: _, .. } => Some("codex package-lock admission refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeExactClosureRefused { closure: _, .. } => Some("codex exact target closure refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeTargetObservationRefused { observation: _, .. } => Some("codex npm runtime target observation refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeAcquisitionRefused { acquisition: _, .. } => Some("codex registry artifact acquisition refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeWorkspaceRefused { cause: cause, .. } => Some(cause.clone()),
    CodexRuntimeMaterialization::CodexRuntimeCacheSeedRefused { .. } => Some("codex isolated npm cache seed refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeNpmCiOfflineRefused { stderr: _, .. } => Some("codex npm ci --offline --ignore-scripts refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeExecutableAbsent { path: _, .. } => Some("codex native executable absent after offline install".to_string()),
    CodexRuntimeMaterialization::CodexRuntimePlatformPackageAbsent { path: _, .. } => Some("codex platform package directory absent after offline install".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeIdentityObservationRefused => Some("codex admitted-package-set identity observation refused".to_string()),
    CodexRuntimeMaterialization::CodexRuntimeReceiptObservationRefused { cause: cause, .. } => Some(cause.clone()),
    CodexRuntimeMaterialization::CodexRuntimeReleaseRefused { cause: cause, .. } => Some(cause.clone()),
    CodexRuntimeMaterialization::CodexRuntimeMaterializationReuseMismatch { cause, .. } => Some(cause.clone()),
    CodexRuntimeMaterialization::CodexRuntimeHostDependencyRefused { .. } => Some("codex runtime host dependency refused".to_string()),
}
}

