pub async fn codex_runtime_install_from_prepared(prepared: Rc<CodexRuntimeClosurePrepareOutcome>, shell_mktemp: &Shell__Mktemp, filesystem: &Filesystem, npm_ci: &Npm__Ci, shell_test: &Shell__Test, http_client: &Http__Client, sha512sum_sha512: &Sha512sum__Sha512, npm_cache: &Npm__Cache) -> std::result::Result<Option<Rc<CodexRuntimePostInstallContext>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*prepared.clone()).clone() {
    CodexRuntimeClosurePrepareOutcome::CodexRuntimeClosurePrepared { source: admitted_source, wrapper, platform, selected_target, platform_lock_key, native_executable_rel, .. } => {
        let staging = shell_mktemp.dir().await?;
if (staging.1.clone() == false) {
            std::option::Option::None
        } else {
            match (*acquire_and_admit_selected_pair(wrapper.clone(), platform.clone(), staging.0.clone(), http_client, sha512sum_sha512).await?).clone() {
    TargetClosureAcquisitionAcc::TargetClosureAcquisitionFailed { acquisition: _, .. } => std::option::Option::None,
    TargetClosureAcquisitionAcc::TargetClosureAcquisitionOk { admitted: admitted, .. } => {
                let cache = shell_mktemp.dir().await?;
if (cache.1.clone() == false) {
                    std::option::Option::None
                } else {
                    match seed_npm_cache_from_admitted(cache.0.clone(), admitted.clone(), npm_cache).await? {
    Some(_) => std::option::Option::None,
    std::option::Option::None => {
                        let build = shell_mktemp.dir().await?;
if (build.1.clone() == false) {
                            std::option::Option::None
                        } else {
                            {
                                let man_dest = v1_rt::concat(build.0.clone(), "/package.json".to_string());
let lock_dest = v1_rt::concat(build.0.clone(), "/package-lock.json".to_string());
let wrote_man = filesystem.write(man_dest.clone(), admitted_source.manifest_bytes.clone()).await?;
let wrote_lock = filesystem.write(lock_dest.clone(), admitted_source.lock_bytes.clone()).await?;
if (wrote_man.0.clone() == false) {
                                    std::option::Option::None
                                } else {
                                    if (wrote_lock.0.clone() == false) {
                                        std::option::Option::None
                                    } else {
                                        {
                                            let installed = npm_ci.ignore_scripts_offline(build.0.clone(), cache.0.clone()).await?;
if (installed.0.clone() == false) {
                                                std::option::Option::None
                                            } else {
                                                {
                                                    let native_path = v1_rt::concat(build.0.clone(), v1_rt::concat("/".to_string(), native_executable_rel.clone()));
let plat_path = v1_rt::concat(build.0.clone(), v1_rt::concat("/".to_string(), platform_lock_key.clone()));
let native_present = shell_test.is_file(native_path.clone()).await?;
let plat_present = shell_test.is_directory(plat_path.clone()).await?;
if (native_present.clone() == false) {
                                                        std::option::Option::None
                                                    } else {
                                                        if (plat_present.clone() == false) {
                                                            std::option::Option::None
                                                        } else {
                                                            Some(Rc::new(CodexRuntimePostInstallContext {
    build_root: build.0.clone(),
    staging_dir: staging.0.clone(),
    cache_dir: cache.0.clone(),
    man_dest: man_dest.clone(),
    lock_dest: lock_dest.clone(),
    native_path: native_path.clone(),
    native_executable_rel: native_executable_rel.clone(),
    platform_lock_key: platform_lock_key.clone(),
    selected_target: selected_target.clone(),
    staged_admitted: admitted.clone(),
}))
                                                        }
                                                    }
}
                                            }
}
                                    }
                                }
}
                        }
},
}
                }
},
}
        }
},
    CodexRuntimeClosurePrepareOutcome::CodexRuntimeClosurePrepareLockRefused { admission: _, .. } => std::option::Option::None,
    CodexRuntimeClosurePrepareOutcome::CodexRuntimeClosurePrepareTargetRefused { observation: _, .. } => std::option::Option::None,
    CodexRuntimeClosurePrepareOutcome::CodexRuntimeClosurePrepareClosureRefused { closure: _, .. } => std::option::Option::None,
    CodexRuntimeClosurePrepareOutcome::CodexRuntimeClosurePrepareHostDependencyRefused { .. } => std::option::Option::None,
})
}

